import React, { useState, useEffect } from "react";
import api from "../services/api";
import "./MLPredictionWidget.css"; // Styling for AI widget

const MLPredictionWidget = () => {
    const [prediction, setPrediction] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState("");

    const fetchPrediction = async () => {
        try {
            const token = localStorage.getItem("token");
            if (!token) {
                setError("Unauthorized: Please log in.");
                setLoading(false);
                return;
            }

            // Fetch latest metrics from backend to make prediction
            const response = await api.get("/api/auth/metrics/", {
                headers: { Authorization: `Token ${token}` },
            });

            if (Array.isArray(response.data) && response.data.length > 0) {
                const latestMetrics = response.data[0];

                // Send the latest metrics for AI prediction
                const predictionResponse = await api.post("/api/ml/predict/", {
                    cpu_usage: latestMetrics.cpu_usage,
                    memory_usage: latestMetrics.memory_usage,
                    disk_usage: latestMetrics.disk_usage,
                    uptime: latestMetrics.uptime,
                }, {
                    headers: { Authorization: `Token ${token}` },
                });

                setPrediction(predictionResponse.data.failure_risk);
            } else {
                setError("No recent metrics available.");
            }
            setLoading(false);
        } catch (err) {
            console.error("Error fetching prediction:", err);
            setError("Failed to fetch prediction.");
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchPrediction();
        const interval = setInterval(fetchPrediction, 30000); // Refresh every 30 seconds
        return () => clearInterval(interval);
    }, []);

    return (
        <div className="widget ml-prediction-widget">
            <h3>AI Predictive Maintenance</h3>
            {loading ? <p>Loading prediction...</p> : error ? <p>{error}</p> : (
                <p>
                    <strong>Failure Risk:</strong> 
                    <span className={prediction ? "risk-high" : "risk-low"}>
                        {prediction ? "HIGH ⚠️" : "LOW ✅"}
                    </span>
                </p>
            )}
        </div>
    );
};

export default MLPredictionWidget;
